@spec pa_track_scope_spec  src=tests/specs/pa_track_scope_spec.lua  loc=89  cases=3
@exercises trackerView (h.vm), editCursor (h.ec), trackerManager (h.tm), dataStore (h.ds), paramAutomation (h.pa)
@surface   vm:setGridSize, ec:setPos, vm:setPaletteParam, vm:automateParam, tm:bindTake, vm:rebuild, vm:paramBinding, ds:get, pa:binding, pa:automate
@harness   mk{seed.notes}, r:setTrackFX, r:setFxGuid, r.TrackFX_GetNamedConfigParm, r:bindTake, r._state.projectTracks, r._state.trackGuids, r._state.projectItems

# Intent
  Bindings are track-scoped, not take-scoped: the param a column drives belongs
  to the track, so a second take on the same track opens with the column already
  there and driving the same plink. And since a target carries one plink,
  re-automating a bound param reuses its lane rather than minting a rival.

# Helpers
  @fn mkScenario(harness)  @ 15-28
      -- The bound take's track plus a target track hosting a synth; projectItems
      -- carries the takes pa's project-wide lane scan walks.
  @fn ccColIndex(h, cc)  @ 30-34
  @fn namedParm(r, track, fxIdx, parm)  @ 36-39

# Cases
  @case 'a bound lane carries its column into a second take on the track'  [harness]  @ 44-60
  @case 're-automating a bound param returns its lane, mints no rival'  [harness]  @ 64-75
  @case 'a param bound on one channel is refused on another'  [harness]  @ 79-86

# Uses (outbound edges)
  @use call vm:setGridSize  @ 25
  @use call ec:setPos  @ 26
  @use call vm:setPaletteParam  @ 47,67
  @use call vm:automateParam  @ 48,68,69
  @use call tm:bindTake  @ 54
